/*\
title: $:/plugins/huwiki/ai/chat-engine.js
type: application/javascript
module-type: library

ChatGPT archive parser and chat tiddler store, no network and no DOM.
\*/
(function(){
"use strict";
var CONVERSATION_TAG="$:/tags/HUWikiAI/Conversation";
var MESSAGE_TAG="$:/tags/HUWikiAI/Message";
var MAX_IMPORT_MESSAGES=600;
var MAX_IMPORT_BATCH=15;
function str(s,max){return String(s===undefined||s===null?"":s).slice(0,max||20000);}
function stamp(v){
  if(v instanceof Date && !isNaN(v.getTime()))return v;
  var n=Number(v),d;
  if(isFinite(n)&&n>0)d=new Date(n<100000000000?n*1000:n);
  else if(typeof v==="string" && v)d=new Date(v);
  return d&&!isNaN(d.getTime())?d:new Date();
}
function cleanTitle(s){return str(s||"Uden titel",140).replace(/[\r\n\u0000-\u001f]/g," ").trim()||"Uden titel";}
function roleOf(node){return node&&node.message&&node.message.author&&node.message.author.role || "";}
function textOf(msg){
  if(!msg||!msg.content)return "";
  var c=msg.content;
  if(typeof c.text==="string")return str(c.text,80000);
  if(!Array.isArray(c.parts))return "";
  return c.parts.map(function(part){
    if(typeof part==="string")return part;
    if(!part||typeof part!=="object")return "";
    if(typeof part.text==="string")return part.text;
    if(part.content_type==="image_asset_pointer")return "[Billede – mediefil er ikke importeret]";
    if(part.content_type==="audio_transcription"&&typeof part.text==="string")return part.text;
    return "";
  }).filter(Boolean).join("\n").slice(0,80000);
}
function pathFromMapping(mapping,leaf){
  var out=[],visited=Object.create(null),cursor=leaf;
  while(cursor && mapping[cursor] && !visited[cursor] && out.length<2500){
    visited[cursor]=true;out.push(mapping[cursor]);cursor=mapping[cursor].parent;
  }
  return out.reverse();
}
function activeMessages(record){
  if(!record||typeof record!=="object")return [];
  var nodes=record.mapping;
  if(!nodes||typeof nodes!=="object"){
    // Simple supplied transcript format: [{role, content}].
    return (Array.isArray(record.messages)?record.messages:[]).map(function(m){return {role:m.role||"user",text:str(m.text||m.content||"",80000),created:stamp(m.created||record.create_time)};})
      .filter(function(m){return (m.role==="user"||m.role==="assistant") && m.text.trim();}).slice(0,MAX_IMPORT_MESSAGES);
  }
  var selected=pathFromMapping(nodes,record.current_node);
  if(!selected.length){
    // An export may omit current_node. Find latest leaf from the mapping.
    var ids=Object.keys(nodes),best="",score=-1;
    ids.forEach(function(id){var nd=nodes[id],msg=nd&&nd.message;
      var t=Number(msg&&msg.create_time)||0;
      if(nd && (!nd.children||!nd.children.length) && t>=score){best=id;score=t;}
    });
    selected=pathFromMapping(nodes,best);
  }
  return selected.map(function(node){var m=node&&node.message;
    return {role:roleOf(node),text:textOf(m),created:stamp(m&&m.create_time||record.create_time)};
  }).filter(function(m){return (m.role==="user"||m.role==="assistant")&&m.text.trim();}).slice(0,MAX_IMPORT_MESSAGES);
}
function parseArchive(payload){
  if(typeof payload==="string")payload=JSON.parse(payload);
  if(!Array.isArray(payload))throw new Error("Forventede conversations.json som et JSON-array.");
  return payload.map(function(rec,i){
    var msgs=activeMessages(rec), name=cleanTitle(rec&&rec.title), date=stamp(rec&&rec.create_time);
    return {id:str(rec&&rec.conversation_id||"record-"+i,120),name:name,created:date,
      messages:msgs,count:msgs.length,preview:msgs.length?str(msgs[0].text,100):"(ingen tekst)"};
  }).filter(function(x){return x.count>0;}).sort(function(a,b){return b.created-a.created;});
}
function createConversation(wiki,Tiddler,name,fields){
  var base="HUWiki AI · Chat · "+cleanTitle(name),title=base,n=2;
  while(wiki.getTiddler(title)){title=base+" ("+(n++)+")";}
  var date=new Date(),extras=fields||{};
  var t={title:title,caption:cleanTitle(name),tags:[CONVERSATION_TAG],type:"text/vnd.tiddlywiki",
    text:"<$huwiki-ai-chat-library conversation=<<currentTiddler>>/>",created:date,modified:date,
    "ai-provider":str(extras.provider||"importeret",60),"ai-origin":str(extras.origin||"HUWiki AI",120),
    "ai-chat-id":str(extras.id||"",160)};
  wiki.addTiddler(new Tiddler(t));return title;
}
function addMessage(wiki,Tiddler,chatTitle,role,text,when,telemetry){
  if(role!=="user"&&role!=="assistant")throw new Error("Ukendt chatrolle");
  if(!wiki.getTiddler(chatTitle))throw new Error("Samtalen findes ikke længere.");
  var existing=wiki.getTiddlersWithTag(chatTitle)||[],numbers=existing.map(function(t){var x=wiki.getTiddler(t);return Number(x&&x.fields["ai-seq"])||0;});
  var num=Math.max.apply(null,[0].concat(numbers))+1,title=chatTitle+" / "+String(num).padStart(5,"0");
  while(wiki.getTiddler(title)){num++;title=chatTitle+" / "+String(num).padStart(5,"0");}
  var date=stamp(when);
  var fields={title:title,tags:[MESSAGE_TAG,chatTitle],type:"text/plain",text:str(text,80000),
    "ai-role":role,"ai-seq":String(num),created:date,modified:date};
  // Store only bounded numeric timing metadata, never prompts, image bytes or credentials.
  if(role==="assistant" && telemetry){
    ["durationMs","remoteMs","serverMs","imagePrepMs","inputTokens","outputTokens","reasoningTokens","generationMs","promptMs"].forEach(function(key){
      var value=Number(telemetry[key]);
      if(isFinite(value)&&value>=0&&value<=36000000)
        fields["ai-"+key.replace(/[A-Z]/g,function(x){return "-"+x.toLowerCase();})]=String(Math.round(value));
    });
    if(telemetry.truncated===true)fields["ai-truncated"]="yes";
    if(telemetry.provider)fields["ai-provider"]=str(telemetry.provider,30);
    if(telemetry.model)fields["ai-model"]=str(telemetry.model,140);
    if(Number(telemetry.outputImageCount)>0&&Number(telemetry.outputImageCount)<=2)fields["ai-output-image-count"]=String(Math.floor(Number(telemetry.outputImageCount)));
  }
  wiki.addTiddler(new Tiddler(fields));
  return title;
}
function messagesFor(wiki,chatTitle){
  return (wiki.getTiddlersWithTag(chatTitle)||[]).map(function(title){var t=wiki.getTiddler(title);if(!t||!t.fields["ai-role"])return null;
    return {title:title,role:t.fields["ai-role"],text:t.fields.text||"",imageRefs:t.fields["ai-images"]||"",outputImageCount:Number(t.fields["ai-output-image-count"])||0,seq:Number(t.fields["ai-seq"])||0,
      telemetry:{durationMs:Number(t.fields["ai-duration-ms"])||0,remoteMs:Number(t.fields["ai-remote-ms"])||0,
        serverMs:Number(t.fields["ai-server-ms"])||0,imagePrepMs:Number(t.fields["ai-image-prep-ms"])||0,
        inputTokens:Number(t.fields["ai-input-tokens"])||0,outputTokens:Number(t.fields["ai-output-tokens"])||0,
        reasoningTokens:Number(t.fields["ai-reasoning-tokens"])||0,truncated:t.fields["ai-truncated"]==="yes",
        generationMs:Number(t.fields["ai-generation-ms"])||0,promptMs:Number(t.fields["ai-prompt-ms"])||0,
        provider:t.fields["ai-provider"]||"",model:t.fields["ai-model"]||""}};
  }).filter(Boolean).sort(function(a,b){return a.seq-b.seq;});
}
function importSelected(wiki,Tiddler,conversations){
  if(!Array.isArray(conversations)||conversations.length>MAX_IMPORT_BATCH)throw new Error("Importér højst "+MAX_IMPORT_BATCH+" samtaler ad gangen.");
  var out=[];conversations.forEach(function(c){
    if(!c||!Array.isArray(c.messages)||!c.messages.length)return;
    var existing=(wiki.getTiddlersWithTag(CONVERSATION_TAG)||[]).some(function(title){
      var x=wiki.getTiddler(title);return x&&x.fields["ai-origin"]==="ChatGPT"&&x.fields["ai-chat-id"]===c.id;
    });
    if(existing){out.push({title:c.name,skipped:true});return;}
    var title=createConversation(wiki,Tiddler,c.name,{provider:"chatgpt",origin:"ChatGPT",id:c.id});
    c.messages.slice(0,MAX_IMPORT_MESSAGES).forEach(function(msg){addMessage(wiki,Tiddler,title,msg.role,msg.text,msg.created);});
    out.push({title:title,skipped:false,count:Math.min(c.messages.length,MAX_IMPORT_MESSAGES)});
  });return out;
}
// Structured drafts from the original Gemini-app concept: nothing is saved until approved.
function parseTiddlerProposals(text){
  var input=str(text,120000),fence=/```(?:json|tiddlers)\s*([\s\S]*?)```/ig,m,objects=[];
  while((m=fence.exec(input))!==null){
    try{var parsed=JSON.parse(m[1]);if(Array.isArray(parsed))objects=objects.concat(parsed);
      else if(parsed && Array.isArray(parsed.tiddlers))objects=objects.concat(parsed.tiddlers);}
    catch(ignore){}
  }
  if(!objects.length){
    try{var direct=JSON.parse(input.trim());objects=Array.isArray(direct)?direct:(direct&&direct.tiddlers||[]);}catch(ignore){}
  }
  return objects.slice(0,12).map(function(t){
    if(!t||typeof t!=="object")return null;
    var title=cleanTitle(t.title),tags=Array.isArray(t.tags)?t.tags:typeof t.tags==="string"?t.tags.split(","):[];
    tags=tags.map(function(v){return str(v,70).trim();}).filter(function(v){return v && !/^[\$]?:\//.test(v) && !/[<>\r\n]/.test(v);}).slice(0,12);
    var body=str(t.text,80000);
    if(!title || title.indexOf("$:/")===0 || !body.trim())return null;
    return {title:title,tags:tags,type:"text/vnd.tiddlywiki",text:body,selected:true};
  }).filter(Boolean);
}
function commitProposals(wiki,Tiddler,proposals,chatTitle){
  var chosen=(proposals||[]).filter(function(t){return t.selected;});
  if(chosen.length>12)throw new Error("Højst 12 tiddlere ad gangen.");
  var seen=Object.create(null);
  chosen.forEach(function(t){
    if(!t.title || t.title.indexOf("$:/")===0 || wiki.getTiddler(t.title) || seen[t.title])throw new Error("Titlen findes allerede eller er reserveret: "+t.title);
    if(!String(t.text||"").trim())throw new Error("En tiddler mangler indhold.");seen[t.title]=true;
  });
  var created=[];
  try{chosen.forEach(function(t){
    wiki.addTiddler(new Tiddler({title:t.title,tags:t.tags||[],text:t.text,
      type:["text/plain","text/vnd.tiddlywiki","text/x-markdown"].indexOf(t.type)!==-1?t.type:"text/plain",
      "ai-created-by":"HUWiki AI","ai-source-chat":chatTitle,
      "ai-source-message":t.sourceMessage||"",created:new Date(),modified:new Date()}));created.push(t.title);
  });}catch(err){created.forEach(function(title){try{wiki.deleteTiddler(title);}catch(ignore){}});throw err;}
  return created;
}
// Conversation metadata is ordinary wiki data. Never store connection IDs or credentials here.
function conversationTags(tags){
  var values=Array.isArray(tags)?tags:String(tags||"").split(","),out=[];
  values.forEach(function(tag){
    tag=str(tag,80).trim();
    if(tag&&tag.indexOf("$:/")!==0&&!/[\[\]<>\r\n]/.test(tag)&&out.indexOf(tag)<0&&out.length<20)out.push(tag);
  });return out;
}
function updateConversation(wiki,Tiddler,title,values){
  var t=wiki.getTiddler(title);
  if(!t||(t.fields.tags||[]).indexOf(CONVERSATION_TAG)<0)throw Error("Samtalen findes ikke.");
  var name=cleanTitle(values.caption),topic=str(values.topic,100).replace(/[\r\n]/g," ").trim();
  var systemTags=(t.fields.tags||[]).filter(function(x){return x.indexOf("$:/")===0;});
  wiki.addTiddler(new Tiddler(t,{caption:name,"ai-topic":topic,
    tags:systemTags.concat(conversationTags(values.tags)),modified:new Date()}));
  return title;
}
function conversations(wiki){
  return (wiki.getTiddlersWithTag(CONVERSATION_TAG)||[]).map(function(title){
    var t=wiki.getTiddler(title);if(!t)return null;
    var messages=messagesFor(wiki,title),models=[],providers=[],last=messages[messages.length-1];
    messages.forEach(function(m){
      var model=m.telemetry.model,provider=m.telemetry.provider;
      if(model&&models.indexOf(model)<0)models.push(model);
      if(provider&&providers.indexOf(provider)<0)providers.push(provider);
    });
    if(!models.length&&t.fields["ai-model"])models.push(t.fields["ai-model"]);
    var time=t.fields.modified||t.fields.created;
    if(last){var lastT=wiki.getTiddler(last.title);if(lastT)time=lastT.fields.modified||lastT.fields.created||time;}
    var numeric=time instanceof Date?time.getTime():Date.parse(String(time||""));
    return {title:title,caption:t.fields.caption||title,topic:t.fields["ai-topic"]||"",
      tags:conversationTags(t.fields.tags||[]),models:models,providers:providers,
      count:messages.length,updated:isFinite(numeric)?numeric:0,
      preview:last?last.text.replace(/\s+/g," ").slice(0,100):"Tom samtale"};
  }).filter(Boolean).sort(function(a,b){return b.updated-a.updated||a.caption.localeCompare(b.caption,"da");});
}
function filterConversations(items,query,tag){
  var needle=String(query||"").toLocaleLowerCase("da-DK").trim();
  return items.filter(function(c){return (!tag||c.tags.indexOf(tag)>=0)&&(!needle||
    [c.caption,c.topic,c.tags.join(" "),c.models.join(" "),c.providers.join(" ")].join(" ").toLocaleLowerCase("da-DK").indexOf(needle)>=0);});
}
exports.conversationTags=conversationTags;
exports.updateConversation=updateConversation;
exports.conversations=conversations;
exports.filterConversations=filterConversations;

exports.CONVERSATION_TAG=CONVERSATION_TAG;
exports.MESSAGE_TAG=MESSAGE_TAG;
exports.parseArchive=parseArchive;
exports.activeMessages=activeMessages;
exports.createConversation=createConversation;
exports.addMessage=addMessage;
exports.messagesFor=messagesFor;
exports.importSelected=importSelected;exports.parseTiddlerProposals=parseTiddlerProposals;exports.commitProposals=commitProposals;
})();
